function versionRange(product: Product): string {
  const first = product.versions[0];
  const last = product.versions[product.versions.length - 1];
  return first === last ? `Odoo ${last}` : `Odoo ${first}–${last}`;
}

export function productSeo(product: Product): { title: string; description: string } {
  const entry = curated[product.technicalName];
  const kind = product.kind === 'theme' ? 'Theme' : 'App';
  const title = entry ? entry.title : pageTitle(`${product.name} — Odoo ${kind}`);

  let description = entry?.description ?? product.summary;
  const facts = ` ${versionRange(product)} · ${product.price === 0 ? 'Free' : product.priceLabel} on the Odoo App Store.`;
  if (!entry?.description && description.length + facts.length <= 165) {
    description = `${description.replace(/\.?$/, '.')}${facts}`;
  }
  return { title, description };
}
